import React, { useState } from 'react';
import './Entreprise.css';
import TabNavigation from '../../components/shared/TabNavigation';
import EquipeSection from './components/EquipeSection';
import VehiculesSection from './components/VehiculesSection';
import TrajetsSection from './components/TrajetsSection';
import ContratsSection from './components/ContratsSection';
import HistoriqueSection from './components/HistoriqueSection';
import NotificationsSection from './components/NotificationsSection';

const Entreprise = () => {
  const [activeTab, setActiveTab] = useState('Tout');

  const tabs = [
    'Tout',
    'Trajets du mois',
    'Véhicules',
    'Équipe',
    'Alertes',
    'Contrats & Conventions',
    'Historique & Statistiques'
  ];

  return (
    <div className="entreprise-container">
      <h1>Entreprise</h1>
      
      {/* Onglets */}
      <TabNavigation tabs={tabs} activeTab={activeTab} setActiveTab={setActiveTab} />

      {/* Card contenant tout le contenu */}
      <div className="entreprise-card">
        {/* Affichage conditionnel selon l'onglet */}
        {(activeTab === 'Tout' || activeTab === 'Équipe') && <EquipeSection />}
        {(activeTab === 'Tout' || activeTab === 'Véhicules') && <VehiculesSection />}
        {(activeTab === 'Tout' || activeTab === 'Trajets du mois') && <TrajetsSection />}
        {(activeTab === 'Tout' || activeTab === 'Contrats & Conventions') && <ContratsSection />}
        {(activeTab === 'Tout' || activeTab === 'Historique & Statistiques') && <HistoriqueSection />}
        {(activeTab === 'Tout' || activeTab === 'Alertes') && <NotificationsSection />}
      </div>
    </div>
  );
};

export default Entreprise;
